import 'package:flutter/foundation.dart';

/// Model representing token consumption metrics, caching statistics, and latency.
@immutable
class AdkTokenUsage {
  /// Creates an [AdkTokenUsage].
  const AdkTokenUsage({
    this.promptTokens = 0,
    this.completionTokens = 0,
    this.totalTokens = 0,
    this.thoughtTokens = 0,
    this.cachedTokens = 0,
    this.toolUsePromptTokens = 0,
    this.trafficType,
    this.latencyMs,
  });

  /// Tokens consumed by the prompt/input turn.
  final int promptTokens;

  /// Tokens generated by the model response.
  final int completionTokens;

  /// Total tokens consumed in the turn (prompt + completion + thoughts).
  final int totalTokens;

  /// Reasoning/thought tokens if supported by the model (for example Gemini 2.5/3.x or Claude).
  final int thoughtTokens;

  /// Cached context tokens reused from an active context cache (`cachedContentTokenCount`).
  final int cachedTokens;

  /// Tokens consumed specifically by tool declarations and tool-use prompts (`toolUsePromptTokenCount`).
  final int toolUsePromptTokens;

  /// Optional traffic tier classification (for example `'ON_DEMAND'` or `'PROVISIONED_THROUGHPUT'`).
  final String? trafficType;

  /// Total generation latency in milliseconds.
  final int? latencyMs;

  /// Effective total token count, falling back to `promptTokens + completionTokens + thoughtTokens` when [totalTokens] is zero.
  int get effectiveTotalTokens =>
      totalTokens > 0 ? totalTokens : (promptTokens + completionTokens + thoughtTokens);

  /// Ratio of [cachedTokens] to [promptTokens] in the range `0.0` to `1.0`.
  double get cacheHitRatio {
    if (promptTokens <= 0 || cachedTokens <= 0) {
      return 0.0;
    }
    return (cachedTokens / promptTokens).clamp(0.0, 1.0);
  }

  /// Whether all token counters are zero.
  bool get isEmpty =>
      promptTokens == 0 &&
      completionTokens == 0 &&
      totalTokens == 0 &&
      thoughtTokens == 0 &&
      cachedTokens == 0 &&
      toolUsePromptTokens == 0;

  /// Whether any token counter is greater than zero.
  bool get isNotEmpty => !isEmpty;

  /// Formatted total token string (for example `"1.2k"` or `"850"`).
  String get formattedTotal {
    final int total = effectiveTotalTokens;
    if (total >= 1000000) {
      return '${(total / 1000000).toStringAsFixed(2)}M';
    }
    if (total >= 1000) {
      return '${(total / 1000).toStringAsFixed(1)}k';
    }
    return total.toString();
  }

  /// Estimates cost in USD based on per-1M-token rates.
  double estimateCostUsd({
    double inputPricePerMillion = 0.15,
    double outputPricePerMillion = 0.60,
    double cachedInputPricePerMillion = 0.0375,
  }) {
    final int uncachedPrompt = (promptTokens - cachedTokens).clamp(0, promptTokens);
    final int outputAndThoughts = completionTokens + thoughtTokens;
    return (uncachedPrompt * inputPricePerMillion / 1000000.0) +
        (cachedTokens * cachedInputPricePerMillion / 1000000.0) +
        (outputAndThoughts * outputPricePerMillion / 1000000.0);
  }

  /// Combines two [AdkTokenUsage] snapshots into a cumulative total.
  AdkTokenUsage operator +(AdkTokenUsage other) {
    final int? combinedLatency = latencyMs == null && other.latencyMs == null
        ? null
        : (latencyMs ?? 0) + (other.latencyMs ?? 0);
    return AdkTokenUsage(
      promptTokens: promptTokens + other.promptTokens,
      completionTokens: completionTokens + other.completionTokens,
      totalTokens: effectiveTotalTokens + other.effectiveTotalTokens,
      thoughtTokens: thoughtTokens + other.thoughtTokens,
      cachedTokens: cachedTokens + other.cachedTokens,
      toolUsePromptTokens: toolUsePromptTokens + other.toolUsePromptTokens,
      trafficType: other.trafficType ?? trafficType,
      latencyMs: combinedLatency,
    );
  }

  /// Copies this [AdkTokenUsage] with updated values.
  AdkTokenUsage copyWith({
    int? promptTokens,
    int? completionTokens,
    int? totalTokens,
    int? thoughtTokens,
    int? cachedTokens,
    int? toolUsePromptTokens,
    String? trafficType,
    int? latencyMs,
  }) {
    return AdkTokenUsage(
      promptTokens: promptTokens ?? this.promptTokens,
      completionTokens: completionTokens ?? this.completionTokens,
      totalTokens: totalTokens ?? this.totalTokens,
      thoughtTokens: thoughtTokens ?? this.thoughtTokens,
      cachedTokens: cachedTokens ?? this.cachedTokens,
      toolUsePromptTokens: toolUsePromptTokens ?? this.toolUsePromptTokens,
      trafficType: trafficType ?? this.trafficType,
      latencyMs: latencyMs ?? this.latencyMs,
    );
  }

  @override
  bool operator ==(Object other) {
    if (identical(this, other)) return true;
    return other is AdkTokenUsage &&
        other.promptTokens == promptTokens &&
        other.completionTokens == completionTokens &&
        other.totalTokens == totalTokens &&
        other.thoughtTokens == thoughtTokens &&
        other.cachedTokens == cachedTokens &&
        other.toolUsePromptTokens == toolUsePromptTokens &&
        other.trafficType == trafficType &&
        other.latencyMs == latencyMs;
  }

  @override
  int get hashCode => Object.hash(
        promptTokens,
        completionTokens,
        totalTokens,
        thoughtTokens,
        cachedTokens,
        toolUsePromptTokens,
        trafficType,
        latencyMs,
      );
}
